/* ---------------- News index ---------------- */
/* Friendlier than the tag itself. Anything not here is title-cased rather
   than left shouting, so a tag invented next week still reads as a word. */
/* Tags are stored in capitals - the picker uppercases whatever is typed, so
   they sort and match as one thing. That is right for the data and wrong for
   a label beside prose, where RECAP reads as a warning. Cased for display
   only; what is stored is untouched.
   Not titleCase, which exists already and deliberately leaves a word that has
   capitals of its own alone so McLean survives - which means it does nothing
   at all to RECAP. This one has to lower the case before it raises it. */
function casedTag(t) {
  return String(t || "").toLowerCase().replace(/\b[a-z]/g, (c) => c.toUpperCase());
}

const TAG_LABEL = {
  RECAP: "Game Recaps", PREVIEW: "Game Previews", FEATURE: "Features",
  NEWS: "Team News", PRESS: "Press Releases", RELEASE: "Press Releases",
  ROSTER: "Roster News", AWARD: "Awards", ALUMNI: "Alumni",
};
const tagLabel = (t) => TAG_LABEL[t]
  || String(t || "").charAt(0) + String(t || "").slice(1).toLowerCase();

/* The order they read in when they exist. Everything else follows, so a tag
   nobody thought of still gets a place rather than being dropped. */
const TAG_ORDER = ["NEWS", "PREVIEW", "RECAP", "FEATURE", "PRESS", "RELEASE"];

function NewsIndexPage({ site, openPost }) {
  const live = (site.news || [])
    .filter(isLive)
    .sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  /* Built from the stories rather than from a list written here: the console
     lets staff invent a tag, so a fixed row of tabs would hold an empty
     section for ever and never show whatever they name next. */
  const kinds = useMemo(() => {
    const n = {};
    for (const p of live) {
      const t = String(p.tag || "").trim().toUpperCase();
      if (t) n[t] = (n[t] || 0) + 1;
    }
    return Object.keys(n)
      .sort((a, b) => {
        const ia = TAG_ORDER.indexOf(a), ib = TAG_ORDER.indexOf(b);
        if (ia !== ib) return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
        return a.localeCompare(b);
      })
      .map((t) => [t, tagLabel(t), n[t]]);
  }, [live]);

  const [kind, setKind] = useSticky("news.kind", "all");
  /* A tag can stop existing - the last story carrying it is edited or taken
     down - and a filter for it would then show an empty page with no way to
     tell why. */
  const active = kind !== "all" && kinds.some(([t]) => t === kind) ? kind : "all";
  const posts = active === "all"
    ? live
    : live.filter((p) => String(p.tag || "").trim().toUpperCase() === active);

  return (
    <main style={{ background: "var(--page)" }}>
      <section className="section" style={{ paddingTop: 40 }}>
        <div className="wrap">
          <h1 className="stitle">News</h1>

          {kinds.length > 1 && (
            <div className="gpsides newskinds">
              <button className={"gpside " + (active === "all" ? "on" : "")}
                onClick={() => setKind("all")}>
                Latest <span className="newskindn">{live.length}</span>
              </button>
              {kinds.map(([t, label, n]) => (
                <button key={t} className={"gpside " + (active === t ? "on" : "")}
                  onClick={() => setKind(t)}>
                  {label} <span className="newskindn">{n}</span>
                </button>
              ))}
            </div>
          )}

          {!posts.length && (
            <div className="emptybox" style={{ marginTop: 24 }}>
              <p style={{ margin: 0, fontWeight: 700, color: "var(--ink)" }}>No stories yet</p>
            </div>
          )}

          {/* Descending prominence: the two most recent, then four, then the
              archive six across. A news index whose every row is the same
              size says this morning and last February matter equally. */}
          {[["lead", posts.slice(0, 2)],
            ["mid", posts.slice(2, 6)],
            ["rest", posts.slice(6)]].map(([tier, items]) => (
            items.length ? (
              <div className={"newstier " + tier} key={tier}>
                {items.map((n, i) => (
                  <article className="newscard" key={n.id}
                    role="link" tabIndex={0} onClick={() => openPost(n.id)}
                    onKeyDown={(e) => (e.key === "Enter" || e.key === " ")
                      && (e.preventDefault(), openPost(n.id))}>
                    {/* The picture and the headline are what decide whether
                        anybody opens it. A tag, a blurb and a byline are three
                        more things to read first. */}
                    <div className="newscardart">
                      <img src={n.image || STOCK_IMAGES[i % STOCK_IMAGES.length]} alt="" loading="lazy"
                        onError={(e) => { e.currentTarget.style.visibility = "hidden"; }} />
                    </div>
                    <div className="newscardbody">
                      <h2 className="newscardtitle">{n.title}</h2>
                      <p className="newscardmeta">{fmtDate(n.date)}</p>
                    </div>
                  </article>
                ))}
              </div>
            ) : null
          ))}
        </div>
      </section>
    </main>
  );
}

